"""Pretabulated minimax grids for Laplace MP2 denominators.

The tables approximate ``1/x`` by ``sum(w * exp(-alpha*x))`` on
``[1, ratio]``.  They are the Takatsuka--Ten-no--Hackbusch minimax data
distributed with Benjamin Helmich-Paris' reference implementation:

* J. Chem. Phys. 129, 044112 (2008), doi:10.1063/1.2958921
* J. Comput. Phys. 321, 927 (2016), doi:10.1016/j.jcp.2016.06.011

Only the practically useful part of the table is retained here.  A caller
must fall back to an exact denominator if the requested range or tolerance
is not covered.
"""

from dataclasses import dataclass

import numpy as np


@dataclass(frozen=True)
class MinimaxLaplaceGrid:
    """A scaled exponential-sum approximation to a positive reciprocal."""

    points: np.ndarray
    weights: np.ndarray
    npoints: int
    normalized_error: float
    denominator_min: float
    denominator_max: float
    table_ratio: float


# Each record is ``ratio npoints error | weights | exponents``.  Errors are
