def _parse_table():
    table = {}
    for raw_line in _TABLE_DATA.strip().splitlines():
        header, weights, points = (part.strip() for part in raw_line.split("|"))
        ratio, npoints, error = header.split()
        key = (float(ratio), int(npoints))
        # Published errors are printed with four significant digits.  Inflate
        # them slightly so the stored value remains a conservative bound after
        # parsing the full-precision parameters in binary64.
        table[key] = (
            float(error) * 1.001,
            np.fromstring(weights, sep=","),
            np.fromstring(points, sep=","),
        )
    return table


_MINIMAX_TABLE = _parse_table()
_TABLE_RATIOS = np.array(sorted({key[0] for key in _MINIMAX_TABLE}))


def make_minimax_laplace_grid(
        denominator_min, denominator_max, tolerance=1e-8, max_points=16):
    """Return the lowest-rank tabulated minimax grid satisfying ``tolerance``.

    ``tolerance`` bounds the maximum absolute error in the normalized
    approximation to ``1/x`` on ``[1, denominator_max/denominator_min]``.
    The physical reciprocal error is therefore bounded by
    ``tolerance / denominator_min``.

    Returns ``None`` when no tabulated grid covers the request.  This is an
    intentional signal to use the exact denominator contraction.
    """
    denominator_min = float(denominator_min)
    denominator_max = float(denominator_max)
    tolerance = float(tolerance)
    max_points = int(max_points)
    if not np.isfinite(denominator_min) or denominator_min <= 0:
        raise ValueError("denominator_min must be finite and positive")
    if not np.isfinite(denominator_max) or denominator_max < denominator_min:
        raise ValueError("denominator_max must be finite and >= denominator_min")
    if not np.isfinite(tolerance) or tolerance <= 0:
        raise ValueError("tolerance must be finite and positive")
    if max_points < 1:
        raise ValueError("max_points must be positive")

    ratio = denominator_max / denominator_min
    enclosing = _TABLE_RATIOS[_TABLE_RATIOS >= ratio]
    if not len(enclosing):
        return None
    table_ratio = float(enclosing[0])

    candidates = sorted(
        (npoints, values)
        for (candidate_ratio, npoints), values in _MINIMAX_TABLE.items()
        if candidate_ratio == table_ratio and npoints <= max_points
    )
    for npoints, (error, normalized_weights, normalized_points) in candidates:
        if error <= tolerance:
            return MinimaxLaplaceGrid(
                points=normalized_points / denominator_min,
                weights=normalized_weights / denominator_min,
                npoints=npoints,
                normalized_error=error,
                denominator_min=denominator_min,
                denominator_max=denominator_max,
                table_ratio=table_ratio,
            )
    return None
